INSERT INTO `pattern` VALUES (1991795862779023362,1991067449709658113,'测试图片','简约','TEXT_GENERATED',NULL,'https://clothingpattern-1317715434.cos.ap-guangzhou.myqcloud.com/pattern/1991067449709658113/1763716112679.png','https://clothingpattern-1317715434.cos.ap-guangzhou.myqcloud.com/1763716112679_thumbnail.png',1557294,'image/png','简约','冬季','大学生',NULL,'PENDING',NULL,NULL,NULL,0,'2025-11-21 09:08:34','2025-11-21 13:20:38',1),(1991796958314450945,1991067449709658113,'北欧简约冬季大学生卫衣平铺图案','设计一款适配大学生日常穿搭的冬季卫衣平铺图案，风格为北欧极简主义，以几何线条为核心元素（细线条菱形+小圆点组合，间距均匀），色彩采用低饱和莫兰迪色系（主色：雾霾蓝+米白，点缀色：浅灰），图案密度适中（不拥挤不稀疏），边缘圆润无尖锐角，质感偏柔软针织纹理，无复杂装饰，百搭不挑性别，适合印在卫衣前胸或衣袖局部区域','TEXT_GENERATED',NULL,'https://clothingpattern-1317715434.cos.ap-guangzhou.myqcloud.com/pattern/1991067449709658113/1763716374316.png','https://clothingpattern-1317715434.cos.ap-guangzhou.myqcloud.com/1763716374316_thumbnail.png',1668516,'image/png','北欧极简主义','冬季','18-22岁大学生（休闲穿搭、日常通勤场景）',NULL,'PENDING',NULL,NULL,NULL,0,'2025-11-21 09:12:55','2025-11-21 13:20:37',1),(1991838960204754945,1991067449709658113,'北欧简约冬季大学生卫衣平铺图案','设计一款适配大学生日常穿搭的冬季卫衣平铺图案，风格为北欧极简主义，以几何线条为核心元素（细线条菱形+小圆点组合，间距均匀），色彩采用低饱和莫兰迪色系（主色：雾霾蓝+米白，点缀色：浅灰），图案密度适中（不拥挤不稀疏），边缘圆润无尖锐角，质感偏柔软针织纹理，无复杂装饰，百搭不挑性别，适合印在卫衣前胸或衣袖局部区域','TEXT_GENERATED',NULL,'https://clothingpattern-1317715434.cos.ap-guangzhou.myqcloud.com/pattern/1991067449709658113/1763726386660.png','https://clothingpattern-1317715434.cos.ap-guangzhou.myqcloud.com/1763726386660_thumbnail.png',2035324,'image/png','北欧极简主义','冬季','18-22岁大学生（休闲穿搭、日常通勤场景）',NULL,'PENDING',NULL,NULL,NULL,0,'2025-11-21 11:59:49','2025-11-21 13:20:37',1),(1991847766707945473,1991067449709658113,'夏日花卉写列','花朵','TEXT_GENERATED','','https://clothingpattern-1317715434.cos.ap-guangzhou.myqcloud.com/pattern/1991067449709658113/1763728486790.png','https://clothingpattern-1317715434.cos.ap-guangzhou.myqcloud.com/1763728486790_thumbnail.png',1415353,'image/png','卡通','春季','成人',NULL,'PENDING',NULL,NULL,NULL,0,'2025-11-21 12:34:48','2025-11-21 13:20:36',1),(19918